const positions = [
  { x: 0, y: 0 },
  { x: 250, y: 120 },
  { x: 250, y: -120 },
  { x: 500, y: 0 },
  { x: 750, y: 120 },
  { x: 750, y: -120 },
  { x: 1000, y: 0 },
  { x: 1250, y: 120 },
  { x: 1250, y: -120 },
  { x: 1500, y: 0 },
];

function generateRoadmap(input: RoadmapInput): Roadmap {
  const roleKey = input.dreamRoleKey || 'other';
  const roleLabel = input.dreamRole || getDreamRoleLabel(roleKey);
  const template = roleTemplates[roleKey] || roleTemplates['other'];
  const phases = template.phases;

  const nodes = phases.map((p, i) => ({
    id: `node-${i}`,
    type: 'skillNode',
    position: positions[i] || { x: i * 250, y: 0 },
    data: { ...p },
  }));

  const edges = [
    { id: 'e0-1', source: 'node-0', target: 'node-1', animated: true },
    { id: 'e0-2', source: 'node-0', target: 'node-2', animated: true },
    { id: 'e1-3', source: 'node-1', target: 'node-3', animated: true },
    { id: 'e2-3', source: 'node-2', target: 'node-3', animated: true },
    { id: 'e3-4', source: 'node-3', target: 'node-4', animated: true },
    { id: 'e3-5', source: 'node-3', target: 'node-5', animated: true },
    { id: 'e4-6', source: 'node-4', target: 'node-6', animated: true },
    { id: 'e5-6', source: 'node-5', target: 'node-6', animated: true },
    { id: 'e6-7', source: 'node-6', target: 'node-7', animated: true },
    { id: 'e6-8', source: 'node-6', target: 'node-8', animated: true },
    { id: 'e7-9', source: 'node-7', target: 'node-9', animated: true },
    { id: 'e8-9', source: 'node-8', target: 'node-9', animated: true },
  ];

  return { career: roleLabel, nodes, edges };
}

export { generateRoadmap };
